package io.floci.aws.services.cur;

import com.fasterxml.jackson.databind.JsonNode;
import io.floci.aws.core.common.RequestConstraintCheck;

/**
 * Checks the Cost and Usage Reports tag operations, and the {@code Tags} of {@code PutReportDefinition},
 * against the constraints generated by {@code tools/aws/regen_cur_shapes.py}.
 */
final class CurRequestShapes {

    private static final RequestConstraintCheck CHECK = RequestConstraintCheck.load(
            "aws/cur-request-shapes.json", "CUR request shapes",
            RequestConstraintCheck.standardMessages("ValidationException"));

    private CurRequestShapes() {
    }

    static void check(String operation, JsonNode request) {
        if (CHECK.hasOperation(operation)) {
            CHECK.check(operation, request);
        }
    }

    /** Checks a request's {@code Tags} member, when it has one, as a {@code TagList}. */
    static void checkTags(JsonNode tags) {
        if (tags != null && !tags.isNull()) {
            CHECK.checkShape("TagList", tags);
        }
    }
}
